import sys, select, socket, time, unittest
from pathlib import Path
from typing import List, Dict

REPO_ROOT = Path('.').resolve()
sys.path.insert(0, str(REPO_ROOT / 'companion'))
sys.path.insert(0, str(REPO_ROOT / 'tests'))

import opentv.core.discovery as d

# Proposed Patches in discovery.py:

# Fix 1 & 2 in discover_ssdp:
orig_discover_ssdp = d.discover_ssdp
def patched_discover_ssdp(
    timeout: float = 3.0,
    resolve_descriptors: bool = True,
    sock: socket.socket = None,
) -> List[d.DiscoveredDevice]:
    close_socket = False
    if sock is None:
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM, socket.IPPROTO_UDP)
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            sock.setblocking(False)
            close_socket = True
        except OSError:
            return []

    packet = d.build_msearch_packet()
    for target in d.SSDP_SEARCH_TARGETS:
        try:
            sock.sendto(packet.replace(b'ssdp:all', target.encode('ascii')), (d.SSDP_MULTICAST_ADDR, d.SSDP_PORT))
        except OSError:
            pass

    devices_by_ip: Dict[str, d.DiscoveredDevice] = {}
    deadline = time.time() + timeout

    try:
        while True:
            remaining = deadline - time.time()
            if remaining <= 0:
                break

            try:
                r, _, _ = select.select([sock], [], [], min(remaining, 0.5))
            except (OSError, ValueError):
                break

            if not r:
                continue

            # Fix 1: continue instead of break
            try:
                data, addr = sock.recvfrom(65535)
            except (BlockingIOError, OSError, socket.error):
                continue

            ip = addr[0]
            status_line, headers = d.parse_ssdp_headers(data)
            if not headers:
                continue

            desc_info: Dict[str, str] = {}
            location = headers.get('LOCATION', '')
            if resolve_descriptors and location:
                desc_info = d.fetch_ssdp_descriptor(location, timeout=min(remaining, 0.5))

            device = d.identify_ssdp_device(headers, ip, desc_info)
            if ip not in devices_by_ip:
                devices_by_ip[ip] = device
            else:
                existing = devices_by_ip[ip]
                # Fix 2: Upgrade model and device_type
                if (existing.model.startswith('Unknown') or existing.model.startswith('Smart TV')) and not (device.model.startswith('Unknown') or device.model.startswith('Smart TV')):
                    existing.model = device.model
                elif existing.model.startswith('Unknown') and not device.model.startswith('Unknown'):
                    existing.model = device.model

                android_types = {'android_tv', 'google_tv', 'fire_tv'}
                if existing.device_type in ('unknown', 'smart_tv') and device.device_type in android_types:
                    existing.device_type = device.device_type
                elif existing.device_type == 'unknown' and device.device_type != 'unknown':
                    existing.device_type = device.device_type
                existing.raw_info.setdefault('additional_responses', []).append(device.raw_info)

        return list(devices_by_ip.values())
    finally:
        if close_socket and sock:
            try:
                sock.close()
            except OSError:
                pass

# Fix 3 & 4 in deduplicate_devices:
orig_deduplicate_devices = d.deduplicate_devices
def patched_deduplicate_devices(
    mdns_devices: List[d.DiscoveredDevice],
    ssdp_devices: List[d.DiscoveredDevice],
) -> List[d.DiscoveredDevice]:
    by_ip: Dict[str, d.DiscoveredDevice] = {}

    for m in mdns_devices:
        by_ip[m.ip] = m

    for s in ssdp_devices:
        if s.ip in by_ip:
            m = by_ip[s.ip]
            best_port = m.port if m.port and m.port != 5555 else (s.port or 5555)
            best_hostname = m.hostname or s.hostname

            # Fix 4:
            if s.model and not s.model.startswith('Unknown') and not s.model.startswith('Smart TV') and (not m.model or m.model.startswith('Android')):
                best_model = s.model
            else:
                best_model = m.model or s.model

            # Fix 3:
            if s.device_type in ('google_tv', 'fire_tv'):
                best_type = s.device_type
            elif m.device_type == 'android_tv':
                best_type = 'android_tv'
            else:
                best_type = m.device_type or s.device_type

            merged_raw = {
                'mdns': m.raw_info,
                'ssdp': s.raw_info,
            }

            by_ip[s.ip] = d.DiscoveredDevice(
                ip=s.ip,
                port=best_port,
                hostname=best_hostname,
                device_type=best_type,
                model=best_model,
                source='mdns+ssdp',
                raw_info=merged_raw,
            )
        else:
            by_ip[s.ip] = s

    def ip_sort_key(dev: d.DiscoveredDevice) -> List[int]:
        try:
            return [int(x) for x in dev.ip.split('.')]
        except ValueError:
            return [999, 999, 999, 999]

    return sorted(by_ip.values(), key=ip_sort_key)

# Apply patches to module
d.discover_ssdp = patched_discover_ssdp
d.deduplicate_devices = patched_deduplicate_devices

# Load adversarial tests
import test_discovery_adversarial as tda
tda.discover_ssdp = patched_discover_ssdp
tda.deduplicate_devices = patched_deduplicate_devices

# Remove expectedFailure from the 4 test cases
tests_to_unfail = [
    'test_expected_fix_discover_ssdp_survives_transient_blocking_io',
    'test_expected_fix_dial_upgraded_to_android_tv',
    'test_expected_fix_dedup_preserves_android_tv_over_roku',
    'test_expected_fix_dedup_does_not_downgrade_to_smart_tv_dial',
]
for tname in tests_to_unfail:
    fn = getattr(tda.TestEmpiricalVulnerabilitiesAndBugs, tname)
    if hasattr(fn, '__unittest_expecting_failure__'):
        delattr(fn, '__unittest_expecting_failure__')

suite = unittest.defaultTestLoader.loadTestsFromModule(tda)
res = unittest.TextTestRunner(verbosity=2).run(suite)

print(f'\nAdversarial suite results with patches applied and expectedFailure removed:')
print(f'Total Tests: {res.testsRun}')
print(f'Failures:    {len(res.failures)}')
print(f'Errors:      {len(res.errors)}')
print(f'ExpectedFailures: {len(res.expectedFailures)}')
print(f'UnexpectedSuccesses: {len(res.unexpectedSuccesses)}')
assert res.wasSuccessful(), 'Suite failed!'
assert res.testsRun == 56, f'Expected 56 tests, got {res.testsRun}'
assert len(res.failures) == 0
assert len(res.errors) == 0
assert len(res.expectedFailures) == 0
assert len(res.unexpectedSuccesses) == 0
print('ALL 56 ADVERSARIAL TESTS PASSED CLEANLY!')
"

